// src/components/globe/GlobeView.jsx
// The 3D globe (react-globe.gl / three.js) IS the game's map — there is no flat SVG map anymore.
// Every country on Earth is a real, playable game region (src/data/regions.js): the 28
// hand-authored ones from the original campaign, plus one whole-country region for every other
// nation (Phase 13's world-region expansion — see scripts/geo/build-world-regions.mjs), each
// rendered using real admin-1 province geometry (see loadGameRegions.js) so the globe reads as an
// actual subdivided map, not flat per-country blobs. Every region is colored by live
// ownership/control and clickable to drive the same selectedRegion/onSelectRegion contract the
// rest of the game (ActionPanel, RegionInfoModal) already expects — there's no separate
// "decorative backdrop" tier anymore, the whole world is the same one system.
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import Globe from 'react-globe.gl';
import { MeshBasicMaterial, Color } from 'three';
import { useGame } from '../../context/GameContext';
import { REGIONS_DATA, getNationCapital } from '../../data/regions';
import { loadGameRegionFeatures } from '../../data/geo/loadGameRegions';
import { REGION_COORDINATES } from '../../data/regionCoordinates';
import { resolveClickedRegionId } from '../../utils/regionClickAssist';
import { useEffects } from '../../context/EffectsContext';
import { useMapInsets } from '../../context/MapInsetsContext';
import GlobeEffectsOverlay, { getFramingPov, getImpactDelay } from './GlobeEffectsOverlay';
import { getAtWarNationIds, getRegionFillColor, getRegionStrokeColor } from '../../utils/mapRegionStyle';

const OCEAN_COLOR = '#0f172a'; // slate-900

const prefersReducedMotion = () =>
  typeof window !== 'undefined' && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;

// Test-only escape hatch: e2e automation sets this (via page.addInitScript, before the app's own
// scripts run) to skip auto-rotate specifically, without going through prefersReducedMotion() —
// that flag ALSO disables the whole GlobeEffectsOverlay below, which a test verifying an
// animation obviously can't afford to lose. Root cause this exists to sidestep (confirmed via a
// Playwright trace with full console/crash instrumentation): under headless, software-rendered
// (SwiftShader) WebGL, the globe's continuous auto-rotate redraw of 4,482 province polygons
// degrades the renderer the longer it runs uninterrupted — a synchronous layout query as ordinary
// as `locator.boundingBox()` on the live canvas can then hang and take the whole page down with
// it. A real player almost always drags the globe within seconds anyway (see the effect below),
// which is what keeps this invisible outside of automation that deliberately never touches it.
// Never true for a real player — nothing in the shipped app ever sets this flag.
const autoRotateDisabledForTests = () =>
  typeof window !== 'undefined' && window.__E2E_DISABLE_GLOBE_AUTOROTATE__ === true;

// Survives a GlobeView/GlobeContainer remount within the same page session (unlike a ref or state
// inside the component, which resets on remount) — once a real player has grabbed the globe, it
// should never resume spinning on its own again for the rest of the session, even if they switch
// tabs/panels in a way that unmounts and remounts the globe. Only a full page reload clears it.
let userDismissedAutoRotate = false;

// Converts react-globe.gl's `altitude` (camera distance above the surface, in globe-radii) into
// the angular half-width/half-height (degrees) of the roughly-circular visible cap, for
// MiniMap.jsx's viewport rectangle — see this component's own onViewportChange effect below for
// the shared `{centerLat, centerLng, halfWidthDeg, halfHeightDeg}` contract Map2DView.jsx also
// reports in. Camera distance from globe center is R(1+altitude); the visible half-angle from the
// center is arccos(R/distance) = arccos(1/(1+altitude)) — standard "horizon angle" trigonometry.
// An approximation (a sphere's visible cap isn't a lat/lng rectangle), but plenty good enough for
// a small minimap indicator, and it's the same approach Civ/Paradox minimaps use for a 3D camera.
const visibleHalfAngleDeg = (altitude) => (Math.acos(1 / (1 + Math.max(altitude, 0.01))) * 180) / Math.PI;

const GlobeView = ({
  width, height, selectedRegion, onSelectRegion, focusRegionId = null, navigateTarget = null, onViewportChange = null
}) => {
  const { state } = useGame();
  const { effects } = useEffects();
  const insets = useMapInsets();
  const globeRef = useRef(null);
  const [geo, setGeo] = useState(null);
  // No globeImageUrl (no texture fetch, no external dependency, matches the stylized/game look
  // over photorealism) — react-globe.gl defaults an untextured globe to solid black, so oceans
  // are given an explicit deep-blue material instead to read clearly against land polygons.
  const globeMaterial = useMemo(() => new MeshBasicMaterial({ color: new Color('#0c2c4d') }), []);

  // The globe auto-rotates (below) — without this, a newly-triggered effect could land anywhere
  // on the sphere, including the far side facing away from the camera, making it invisible.
  // Moving the camera and pausing rotation is what actually makes the animation something the
  // player sees rather than something that technically fired offscreen. It runs as a two-beat
  // camera move: first frame the WHOLE trajectory (getFramingPov centres on the midpoint and
  // pulls back far enough for the launch site and the target to share the screen, so the arc is
  // watchable end to end), then punch in on the target at the exact moment of impact.
  const lastEffectId = useRef(null);
  const shakeRef = useRef(null);
  useEffect(() => {
    if (!effects || effects.length === 0) return undefined;
    const latest = effects[effects.length - 1];
    if (latest.id === lastEffectId.current) return undefined;
    lastEffectId.current = latest.id;
    const to = REGION_COORDINATES[latest.toRegionId];
    if (!to || !globeRef.current) return undefined;
    const controls = globeRef.current.controls();
    if (controls) controls.autoRotate = false;

    const framing = getFramingPov(latest.fromRegionId, latest.toRegionId)
      || { lat: to.lat, lng: to.lng, altitude: 0.4 };
    globeRef.current.pointOfView(framing, 520);

    if (prefersReducedMotion()) return undefined;
    const punch = setTimeout(() => {
      globeRef.current?.pointOfView({ lat: to.lat, lng: to.lng, altitude: 0.22 }, 620);
      // Restarting a CSS animation needs the name cleared and a reflow forced in between,
      // otherwise a second strike in quick succession wouldn't shake at all.
      const node = shakeRef.current;
      if (node) {
        node.style.animation = 'none';
        void node.offsetWidth;
        node.style.animation = '';
        node.classList.remove('globe-impact-shake');
        void node.offsetWidth;
        node.classList.add('globe-impact-shake');
      }
    }, getImpactDelay(latest.actionType));
    return () => clearTimeout(punch);
  }, [effects]);

  useEffect(() => {
    let cancelled = false;
    loadGameRegionFeatures().then((f) => { if (!cancelled) setGeo(f); });
    return () => { cancelled = true; };
  }, []);

  // Flies to the player's home turf on first load so the game opens somewhere meaningful instead
  // of wherever react-globe.gl's own default camera position happens to be.
  useEffect(() => {
    if (!geo || !globeRef.current) return;
    const home = REGION_COORDINATES[getNationCapital(state.playerNationId)];
    if (!home) return;
    globeRef.current.pointOfView({ lat: home.lat, lng: home.lng, altitude: 1.4 }, 0);
  }, [geo, state.playerNationId]);

  // Bug fix (plan feedback: "on army tab u see in map sweden and not the selected region"):
  // opening ProvinceModal ("Manage Region") never moved the camera at all, so whatever the globe
  // happened to be pointed at (wherever it last drifted to, e.g. from auto-rotate) stayed on
  // screen behind the modal — completely unrelated to the region actually being managed.
  // MapContainer.jsx passes `focusRegionId` = the region ProvinceModal is currently open for (null
  // otherwise), so this flies there the moment Manage Region opens, independent of which of its
  // tabs is active (switching tabs doesn't change `focusRegionId`, so it won't re-fire pointlessly).
  useEffect(() => {
    if (!focusRegionId || !globeRef.current) return;
    const target = REGION_COORDINATES[focusRegionId];
    if (!target) return;
    globeRef.current.pointOfView({ lat: target.lat, lng: target.lng, altitude: 1.0 }, 500);
  }, [focusRegionId]);

  // MiniMap.jsx's "click/drag to navigate" request — see Map2DView.jsx's own navigateTarget effect
  // for why this needs a freshly-created `{lat,lng}` object every time (so navigating to the same
  // spot twice in a row still re-fires). Keeps whatever altitude the player is already at rather
  // than resetting zoom, the same way a real map app's minimap-click only pans, never re-zooms.
  useEffect(() => {
    if (!navigateTarget || !globeRef.current) return;
    const current = globeRef.current.pointOfView();
    globeRef.current.pointOfView({ lat: navigateTarget.lat, lng: navigateTarget.lng, altitude: current?.altitude || 1.4 }, 500);
  }, [navigateTarget]);

  // Reports this view's own visible area so MiniMap.jsx can draw a real "you are here" rectangle —
  // see visibleHalfAngleDeg's own comment above for the shared contract and the approximation it's
  // built on. react-globe.gl/three's OrbitControls don't expose a clean "camera settled" event
  // worth wiring up just for this, so a light poll is simplest; 400ms is imperceptible for a small
  // corner indicator that only needs to be roughly current, not frame-accurate.
  useEffect(() => {
    if (!onViewportChange) return undefined;
    const interval = setInterval(() => {
      const pov = globeRef.current?.pointOfView?.();
      if (!pov) return;
      const halfDeg = visibleHalfAngleDeg(pov.altitude);
      onViewportChange({ centerLat: pov.lat, centerLng: pov.lng, halfWidthDeg: halfDeg, halfHeightDeg: halfDeg });
    }, 400);
    return () => clearInterval(interval);
  }, [onViewportChange]);

  // Auto-rotate is a nice "alive" default for a menu-screen-style globe, but it's motion a
  // reduced-motion user explicitly asked not to see, and it should stop as soon as they've
  // actually grabbed the globe (dragging while it spins fights the user's own input).
  useEffect(() => {
    const controls = globeRef.current?.controls();
    if (!controls) return;
    controls.autoRotate = !userDismissedAutoRotate && !prefersReducedMotion() && !autoRotateDisabledForTests();
    controls.autoRotateSpeed = 0.4;
    const stopOnInteract = () => {
      controls.autoRotate = false;
      userDismissedAutoRotate = true;
    };
    controls.addEventListener('start', stopOnInteract);
    return () => controls.removeEventListener('start', stopOnInteract);
  }, [geo]);

  // Precomputed once per wars/playerNationId change rather than once per polygon — capColor below
  // is invoked for every one of the ~4,482 polygons on every recompute, so an O(#wars) isWarBetween
  // scan per polygon (O(#polygons x #wars) total) would otherwise be repeated needlessly per region.
  const atWarNationIds = useMemo(() => getAtWarNationIds(state.wars, state.playerNationId), [state.wars, state.playerNationId]);

  // useCallback (scoped only to the state slices actually read here, not the whole `state` object)
  // is what makes react-globe.gl's own reference-equality prop diff actually skip work: without it,
  // this closure — and therefore every polygon accessor prop passed to <Globe> below — gets a new
  // identity on every GlobeView render (i.e. on every dispatched game action, even a tax-rate change
  // that never touches a region), which forces three-globe to re-walk and re-color all ~4,482
  // polygons regardless of whether anything actually changed. See plan item 6 for the full trace.
  // fillColorForRegion/getRegionStrokeColor are shared with Map2DView (src/utils/mapRegionStyle.js)
  // so the globe and the flat map always agree on what a region looks like.
  const capColor = useCallback(
    (feature) => getRegionFillColor(state.regions, state.playerNationId, feature.properties?.gameRegionId),
    [state.regions, state.playerNationId]
  );

  // Polygon geometry is real admin-1 provinces (loadGameRegions.js), and since the full
  // province-level split (Task 51) every one of those provinces is its own clickable, independently
  // owned/controlled gameRegionId — unlike the old one-gameRegionId-per-country model this stroke
  // logic was originally written for. Defaulting the stroke to plain black keeps every clickable
  // province edge visible against any fill color. A region owned by a nation you're at war with
  // gets a red outline instead of black — the war signal lives on the stroke, not the fill, so a
  // hostile nation's own color identity (capColor above) stays visible the whole time you're
  // fighting it, not just before or after.
  const strokeColor = useCallback(
    (feature) => getRegionStrokeColor(state.regions, state.playerNationId, feature.properties?.gameRegionId, selectedRegion, atWarNationIds),
    [selectedRegion, state.regions, state.playerNationId, atWarNationIds]
  );

  const altitude = useCallback((feature) => {
    const gameRegionId = feature.properties?.gameRegionId;
    if (gameRegionId === selectedRegion) return 0.03;
    if (state.regions[gameRegionId]?.underInvasion) return 0.02;
    if (state.regions[gameRegionId]?.owner === state.playerNationId) return 0.018;
    return 0.012;
  }, [selectedRegion, state.regions, state.playerNationId]);

  const label = useCallback((feature) => {
    const gameRegionId = feature.properties?.gameRegionId;
    const regionData = REGIONS_DATA[gameRegionId];
    const regionState = state.regions[gameRegionId];
    if (!regionData || !regionState) return '';
    const isPlayerOwned = regionState.owner === state.playerNationId;
    const ownerName = isPlayerOwned ? 'You' : (state.nations[regionState.owner]?.name || regionState.owner);
    const provinceName = feature.properties?.name;
    const subtitle = provinceName && provinceName !== regionData.name ? `${provinceName} &middot; ` : '';
    return `
      <div style="background:#0f172a;color:#e2e8f0;padding:6px 10px;border-radius:6px;font:12px sans-serif;border:1px solid #334155">
        <strong>${regionData.name}</strong><br/>
        <span style="color:#94a3b8">${subtitle}${ownerName}${isPlayerOwned ? ` &middot; ${regionState.control || 0}%` : ''}</span>
      </div>
    `;
  }, [state.regions, state.nations, state.playerNationId]);

  // lat/lng -> on-screen pixel + horizon-visibility, for the click-assist below. The visibility
  // check is the same P·C >= R² horizon test GlobeEffectsOverlay.jsx already uses for its own
  // screen-space projections (a point at world position P is hidden behind the globe's limb
  // exactly when P·C < R², C = camera position, R = globe radius) — getCoords already returns P at
  // its true radius-scaled magnitude, so no separate normalization step is needed here.
  const projectToScreen = useCallback((lat, lng) => {
    const globe = globeRef.current;
    if (!globe) return null;
    const camera = globe.camera?.();
    const camPos = camera?.position;
    const radius = globe.getGlobeRadius?.() || 100;
    const camDist = camPos ? Math.hypot(camPos.x, camPos.y, camPos.z) : 0;
    const p = globe.getCoords(lat, lng, 0);
    const visible = !camPos || camDist <= radius || (p.x * camPos.x + p.y * camPos.y + p.z * camPos.z) >= radius * radius;
    const { x, y } = globe.getScreenCoords(lat, lng, 0);
    return { x, y, visible };
  }, []);

  // Small regions are genuinely hard to hit exactly (a real, reported problem — tapping one kept
  // selecting a larger neighbor instead), so a click first checks whether some region's centroid
  // projects closer to the actual click point than a normal click needs to land, and prefers that
  // over react-globe.gl's own raw polygon hit when one exists. offsetX/offsetY are relative to the
  // canvas itself (the click's event.target), which is exactly the coordinate space
  // getScreenCoords uses. Utterly inert for an ordinary click deep inside a normal-sized region:
  // no other region's centroid will be anywhere near it, so the raw hit always wins.
  //
  // Bug fix (plan feedback: "still can't pick Tel Aviv"): the assist used to search ALL regions for
  // the closest centroid within a flat 24px tolerance, with no regard for how good the RAW hit
  // already was. Tel Aviv is a tiny sliver whose own label point isn't always the very closest
  // thing on screen to every click that lands validly inside it — HaMerkaz (the much bigger
  // district it sits inside) has its own label point nearby, and it sometimes won that "closest
  // centroid" contest even when the click had already landed precisely on Tel Aviv's own polygon,
  // silently overriding a correct pick with the wrong, bigger neighbor. resolveClickedRegionId
  // (regionClickAssist.js) fixes this: the assist may now only replace the raw hit with a candidate
  // SMALLER (by on-screen `extent`) than whatever region was actually hit — it can still rescue a
  // genuine miss (click landed on a big neighbor, but a small region's label is nearer), it just
  // can never redirect away from a region that's already the smallest thing under the cursor. See
  // regionClickAssist.js's own header for why comparing label distance alone wasn't sufficient.
  const handleClick = useCallback((feature, event) => {
    const rawId = feature.properties?.gameRegionId;
    if (!rawId) return;
    const gameRegionId = event ? resolveClickedRegionId(rawId, REGION_COORDINATES, projectToScreen, event.offsetX, event.offsetY) : rawId;
    onSelectRegion(gameRegionId === selectedRegion ? null : gameRegionId);
  }, [selectedRegion, onSelectRegion, projectToScreen]);

  // Memoized so polygonsData keeps a STABLE reference across re-renders that don't actually
  // change the underlying geometry (e.g. a GameContext update from an unrelated action) — a new
  // array identity every render would make react-globe.gl treat it as entirely new data and
  // rebuild every polygon mesh on every render instead of just once.
  const polygons = useMemo(() => geo?.gameRegionFeatures || null, [geo]);

  if (!geo) {
    return (
      <div className="w-full h-full flex items-center justify-center text-slate-400 text-sm">
        Loading world map…
      </div>
    );
  }

  return (
    <div className="relative w-full h-full overflow-hidden">
      {/* RegionInfoModal/MapLegend now live one level up, in MapContainer.jsx, so they overlay
          whichever main view (this globe, or the flat 2D map) is currently active rather than
          being duplicated inside each renderer. */}
      {/* The globe and its effects overlay share one wrapper so the impact shake moves them
          together — shaking the canvas alone would slide the map out from under the animation.
          The panel chrome (legend, region card) deliberately sits outside it and stays still. */}
      {/* Plan §5.1: shifted so the globe's centre — where every camera move (Manage Region focus,
          effect framing, minimap navigation) puts its target — sits in the middle of the part of
          the screen NOT covered by panels (MapInsetsContext), instead of under a bottom sheet.
          A CSS transform rather than resizing the canvas: no three.js reflow as sheets move, and
          pointer events/getScreenCoords stay consistent because the overlay moves with it. */}
      <div
        className="absolute inset-0"
        style={{
          transform: `translate(${(insets.left - insets.right) / 2}px, ${(insets.top - insets.bottom) / 2}px)`,
          transition: 'transform 280ms ease'
        }}
      >
      <div ref={shakeRef} className="absolute inset-0">
      <Globe
        ref={globeRef}
        width={width}
        height={height}
        backgroundColor={OCEAN_COLOR}
        showGlobe
        showAtmosphere
        atmosphereColor="#38bdf8"
        atmosphereAltitude={0.15}
        globeMaterial={globeMaterial}
        polygonsData={polygons}
        polygonCapColor={capColor}
        polygonSideColor={() => 'rgba(15, 23, 42, 0.6)'}
        polygonStrokeColor={strokeColor}
        polygonAltitude={altitude}
        polygonCapCurvatureResolution={12}
        polygonsTransitionDuration={200}
        polygonLabel={label}
        onPolygonClick={handleClick}
      />
      {!prefersReducedMotion() && (
        <GlobeEffectsOverlay globeRef={globeRef} width={width} height={height} effects={effects} ageId={state.age} />
      )}
      </div>
      </div>
    </div>
  );
};

export default GlobeView;
